import json
import os
import sys
from urllib.parse import urlparse

mode = sys.argv[1]
if mode not in ("--demo", "--live"):
    raise SystemExit("Use --demo or --live")
url = os.environ.get("HOOD_BACKEND_URL", "").rstrip("/")
p = urlparse(url)
if mode == "--live" and (
    p.scheme != "https"
    or not p.netloc
    or p.username
    or p.password
    or p.path
    or p.query
    or p.fragment
):
    raise SystemExit(
        "Set HOOD_BACKEND_URL to your HTTPS origin, e.g. https://hood.example.com"
    )
open("src/pkjs/settings.js", "w").write(
    "// Generated by scripts/build-settings.py. No credentials.\nmodule.exports = "
    + json.dumps({"backend": url, "demo": mode == "--demo"})
    + ";\n"
)
